import {listLayout} from './list-layout.js';
export function createVirtualList(element,{items=[],rowHeight=40,variable=false,tree=false,label=item=>String(item?.text??item),select=()=>{},selected=-1}={}){
 const document=element.ownerDocument,content=document.createElement('div'),pool=[],expanded=new Set();content.style.position='relative';element.replaceChildren(content);element.style.overflow='auto';element.style.position||='relative';element.setAttribute('role',tree?'tree':'listbox');element.tabIndex=0;
 let disposed=false,current=items,chosen=selected,layout=listLayout(items,{rowHeight,variable,tree,expanded});
 function rebuild(){const id=layout.rows[chosen]?.key;layout=listLayout(current,{rowHeight,variable,tree,expanded});chosen=tree?layout.rows.findIndex(r=>r.key===id):Math.min(chosen,layout.rows.length-1);}
 function toggle(index){const row=layout.rows[index];if(!row?.branch)return;expanded.has(row.key)?expanded.delete(row.key):expanded.add(row.key);rebuild();update();}
 function update(){
  if(disposed)return;content.style.height=layout.total+'px';const {start,end}=layout.range(element.scrollTop,element.clientHeight||160),count=end-start;
  while(pool.length<count){const row=document.createElement('button');row.type='button';Object.assign(row.style,{position:'absolute',left:'0',width:'100%',textAlign:'start',border:'0',margin:'0',background:'transparent',color:'inherit'});
   row.onclick=event=>{chosen=Number(row.dataset.index);const r=layout.rows[chosen];if(tree&&r.branch&&event.clientX-row.getBoundingClientRect().left<r.depth*16+16){toggle(chosen);return;}select(chosen,r.item);update();};pool.push(row);content.append(row);}
  for(let i=0;i<pool.length;i++){const row=pool[i],index=start+i,r=layout.rows[index];row.hidden=i>=count;if(row.hidden)continue;row.dataset.index=String(index);row.style.top=layout.offsets[index]+'px';row.style.height=r.height+'px';row.style.paddingInlineStart=(tree?(r.depth-1)*16+8:8)+'px';row.textContent=(tree?(r.branch?(expanded.has(r.key)?'▾ ':'▸ '):'  '):'')+label(r.item,index);row.setAttribute('role',tree?'treeitem':'option');row.setAttribute('aria-posinset',String(tree?r.position:index+1));row.setAttribute('aria-setsize',String(tree?r.siblings:layout.rows.length));if(tree){row.setAttribute('aria-level',String(r.depth));if(r.branch)row.setAttribute('aria-expanded',String(expanded.has(r.key)));else row.removeAttribute('aria-expanded');}row.setAttribute('aria-selected',String(index===chosen));row.tabIndex=index===chosen?0:-1;row.style.background=index===chosen?'var(--ui-accent, #365778)':'transparent';}
 }
 function key(event){
  if(!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Home','End','Enter',' '].includes(event.key)||!tree&&['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();if(!layout.rows.length)return;
  if(event.key==='Enter'||event.key===' '){if(chosen>=0)select(chosen,layout.rows[chosen].item);return;}
  const row=layout.rows[chosen];if(tree&&event.key==='ArrowRight'){if(row?.branch&&!expanded.has(row.key)){toggle(chosen);return;}if(row?.branch)chosen++;}
  else if(tree&&event.key==='ArrowLeft'){if(row?.branch&&expanded.has(row.key)){toggle(chosen);return;}if(row?.parent)chosen=layout.rows.findIndex(r=>r.key===row.parent);}
  else chosen=Math.max(0,Math.min(layout.rows.length-1,event.key==='Home'?0:event.key==='End'?layout.rows.length-1:chosen+(event.key==='ArrowUp'?-1:1)));
  chosen=Math.max(0,Math.min(layout.rows.length-1,chosen));const top=layout.offsets[chosen],bottom=layout.offsets[chosen+1];if(top<element.scrollTop)element.scrollTop=top;else if(bottom>element.scrollTop+element.clientHeight)element.scrollTop=bottom-element.clientHeight;update();pool.find(row=>!row.hidden&&Number(row.dataset.index)===chosen)?.focus();select(chosen,layout.rows[chosen].item);
 }
 element.addEventListener('scroll',update);element.addEventListener('keydown',key);const observer=new ResizeObserver(update);observer.observe(element);update();
 return {update,configure(next){if(rowHeight===next.rowHeight&&variable===next.variable)return;rowHeight=next.rowHeight;variable=next.variable;rebuild();update();},items(next){current=next;rebuild();update();},selection(index){chosen=index>=0&&index<layout.rows.length?index:-1;update();},selectionByKey(key){chosen=layout.rows.findIndex(r=>r.key===key);update();},expand(id,value=true){value?expanded.add(id):expanded.delete(id);rebuild();update();},dispose(){disposed=true;observer.disconnect();element.removeEventListener('scroll',update);element.removeEventListener('keydown',key);element.replaceChildren();},get count(){return pool.length;}};
}
